=\"260.04\">设置</text></g></svg><button class=\"mono-core\" type=\"button\" onclick=\"openApp('blazer')\" aria-label=\"查看伐刀者档案\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\" aria-hidden=\"true\" class=\"mono-aperture\" fill=\"currentColor\"><polygon points=\"16.63,1.47 28.58,8.37 21.71,16.16 19.95,11.31\"/><polygon points=\"28.90,9.28 28.90,23.08 18.72,21.03 22.03,17.07\"/><polygon points=\"28.27,23.81 16.32,30.71 13.00,20.87 18.09,21.76\"/><polygon points=\"15.37,30.53 3.42,23.63 10.29,15.84 12.05,20.69\"/><polygon points=\"3.10,22.72 3.10,8.92 13.28,10.97 9.97,14.93\"/><polygon points=\"3.73,8.19 15.68,1.29 19.00,11.13 13.91,10.24\"/></svg><span>操作</span></button><div class=\"mono-wheel-caption\"><b id=\"mono-wheel-label\">选择应用</b><small>SELECT COMMAND</small></div></div><div class=\"app-grid\">\n        <div class=\"app-btn app-blazer\" onclick=\"openApp('blazer')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-shield-check\"></i></div>\n          <span class=\"app-name\">伐刀者档案</span>\n        </div>\n        <div class=\"app-btn app-lime\" onclick=\"openApp('lime')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-messages\"></i><span class=\"app-badge\" id=\"badge-lime\" style=\"display:none\">1</span></div>\n          <span class=\"app-name\">破军LIME</span>\n        </div>\n        <div class=\"app-btn app-moments\" onclick=\"openApp('moments')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-sparkles\"></i></div>\n          <span class=\"app-name\">学园圈</span>\n        </div>\n        <div class=\"app-btn app-bbs\" onclick=\"openApp('bbs')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-news\"></i></div>\n          <span class=\"app-name\">破军BBS</span>\n        </div>\n        <div class=\"app-btn app-schedule\" onclick=\"openApp('schedule')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-radar-2\"></i></div>\n          <span class=\"app-name\">选拔赛程</span>\n        </div>\n        <div class=\"app-btn app-gallery\" onclick=\"openApp('gallery')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-photo\"></i></div>\n          <span class=\"app-name\">灵装画廊</span>\n        </div>\n        <div class=\"app-btn app-world\" onclick=\"openApp('worldbook')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-world\"></i></div>\n          <span class=\"app-name\">世界之理</span>\n        </div>\n        <div class=\"app-btn app-settings\" onclick=\"openApp('settings')\">\n          <div class=\"app-icon-wrap\"><i class=\"ti ti-settings\"></i></div>\n          <span class=\"app-name\">终端配置</span>\n        </div>\n      </div>\n      <div class=\"mono-home-note\"><span>点击扇区进入 · 黑白反转选中</span><span>HAGUN / 01</span></div>\n    </div>\n  </div>\n\n  <!-- 2. 伐刀者档案 (Blazer ID & Radar) -->\n  <div class=\"scr\" id=\"scr-blazer\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">伐刀者能力档案</span>\n      <span class=\"sub\" id=\"blazer-head-rank\">F级 伐刀者</span>\n    </div>\n    <div class=\"subtabs\">\n      <div class=\"subtab on\" data-btab=\"overview\" onclick=\"switchBlazerTab('overview')\">综合概况</div>\n      <div class=\"subtab\" data-btab=\"radar\" onclick=\"switchBlazerTab('radar')\">六维雷达</div>\n      <div class=\"subtab\" data-btab=\"device\" onclick=\"switchBlazerTab('device')\">灵装绝技</div>\n      <div class=\"subtab\" data-btab=\"roster\" onclick=\"switchBlazerTab('roster')\">同伴名册</div>\n    </div>\n    <div class=\"body\" id=\"blazer-body\"></div>\n  </div>\n\n  <!-- 3. 破军 LIME 通讯 -->\n  <div class=\"scr\" id=\"scr-lime\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\" id=\"lime-title\">破军 LIME</span>\n      <span class=\"sub\" id=\"lime-sub\">专网加密连线</span>\n    </div>\n    <div class=\"body\" id=\"lime-body\"></div>\n  </div>\n\n  <!-- 4. 学园圈 (Moments) -->\n  <div class=\"scr\" id=\"scr-moments\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">学园圈 (Moments)</span>\n      <span class=\"act\"><button onclick=\"postMomentPrompt()\"><i class=\"ti ti-plus\"></i> 发动态</button></span>\n    </div>\n    <div class=\"body\" id=\"moments-body\"></div>\n  </div>\n\n  <!-- 5. 破军BBS 论坛 -->\n  <div class=\"scr\" id=\"scr-bbs\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">破军 BBS // 选拔战板</span>\n      <span class=\"act\"><button onclick=\"refreshBbs()\"><i class=\"ti ti-refresh\"></i> 刷新</button></span>\n    </div>\n    <div class=\"body\" id=\"bbs-body\"></div>\n  </div>\n\n  <!-- 6. 选拔赛程 (Schedule) -->\n  <div class=\"scr\" id=\"scr-schedule\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">选拔赛程与决斗</span>\n    </div>\n    <div class=\"body\" id=\"schedule-body\"></div>\n  </div>\n\n  <!-- 7. 灵装画廊 (Gallery) -->\n  <div class=\"scr\" id=\"scr-gallery\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">灵装与战术相册</span>\n    </div>\n    <div class=\"body\" id=\"gallery-body\"></div>\n  </div>\n\n  <!-- 8. 世界之理 (Worldbook) -->\n  <div class=\"scr\" id=\"scr-worldbook\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">世界之理 (世界书)</span>\n    </div>\n    <div class=\"body\" id=\"worldbook-body\"></div>\n  </div>\n\n  <!-- 9. 终端配置 (Settings) -->\n  <div class=\"scr\" id=\"scr-settings\">\n    <div class=\"apphead\">\n      <button class=\"back\" onclick=\"goBack()\"><i class=\"ti ti-chevron-left\"></i></button>\n      <span class=\"t\">终端配置</span>\n    </div>\n    <div class=\"body\" id=\"settings-body\"></div>\n  </div>\n\n</div>\n\n<!-- 底部 Homebar -->\n<div id=\"homebar\">\n<button onclick=\"goBack()\" title=\"返回上一页\">← 返回</button><button onclick=\"goHome()\" title=\"返回主界面\"><svg xmlns=\"http://www.w3.org/2000/svg\" class=\"\" viewBox=\"0 0 16 16\" width=\"12\" height=\"12\" fill=\"currentColor\" shape-rendering=\"crispEdges\" aria-hidden=\"true\"><rect x=\"7\" y=\"2\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"2\" width=\"1\" height=\"1\"/><rect x=\"6\" y=\"3\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"3\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"3\" width=\"1\" height=\"1\"/><rect x=\"9\" y=\"3\" width=\"1\" height=\"1\"/><rect x=\"5\" y=\"4\" width=\"1\" height=\"1\"/><rect x=\"6\" y=\"4\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"4\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"4\" width=\"1\" height=\"1\"/><rect x=\"9\" y=\"4\" width=\"1\" height=\"1\"/><rect x=\"10\" y=\"4\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"5\" width=\"1\" height=\"1\"/><rect x=\"5\" y=\"5\" width=\"1\" height=\"1\"/><rect x=\"6\" y=\"5\" width=\"1\" height=\"1\"/><rect x=\"9\" y=\"5\" width=\"1\" height=\"1\"/><rect x=\"10\" y=\"5\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"5\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"6\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"6\" width=\"1\" height=\"1\"/><rect x=\"5\" y=\"6\" width=\"1\" height=\"1\"/><rect x=\"10\" y=\"6\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"6\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"6\" width=\"1\" height=\"1\"/><rect x=\"2\" y=\"7\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"7\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"7\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"7\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"7\" width=\"1\" height=\"1\"/><rect x=\"13\" y=\"7\" width=\"1\" height=\"1\"/><rect x=\"1\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"2\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"5\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"6\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"9\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"10\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"13\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"14\" y=\"8\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"9\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"9\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"9\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"9\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"10\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"10\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"10\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"10\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"10\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"10\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"11\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"11\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"11\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"11\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"11\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"11\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"12\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"12\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"12\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"12\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"12\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"12\" width=\"1\" height=\"1\"/><rect x=\"3\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"4\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"5\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"6\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"7\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"8\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"9\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"10\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"11\" y=\"13\" width=\"1\" height=\"1\"/><rect x=\"12\" y=\"13\" width=\"1\" height=\"1\"/></svg> 终端首页</button><button onclick=\"if(bridge &amp;&amp; bridge.ui) bridge.ui.close()\" title=\"收起终端\">× 收起</button>\n</div>\n\n<!-- 提醒浮条 -->\n<div id=\"toast\"></div>\n\n<script>\n\"use strict\";\n\nvar bridge = null;\nvar stat = {};\nvar currentStack = ['scr-home'];\nvar blazerSubTab = 'overview';\nvar activeChat = null;\n\nfunction esc(s) {\n  if (s == null) return '';\n  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n}\n\nfunction toast(msg) {\n  var t = document.getElementById('toast');\n  if (!t) return;\n  t.textContent = msg;\n  t.classList.add('on');\n  clearTimeout(t._timer);\n  t._timer = setTimeout(function() { t.classList.remove('on'); }, 2200);\n}\n\n// 导航操作\nfunction openApp(appId) {\n  var scrMap = {\n    'blazer': 'scr-blazer',\n    'lime': 'scr-lime',\n    'moments': 'scr-moments',\n    'bbs': 'scr-bbs',\n    'schedule': 'scr-schedule',\n    'gallery': 'scr-gallery',\n    'worldbook': 'scr-worldbook',\n    'settings': 'scr-settings'\n  };\n  var target = scrMap[appId];\n  if (!target) return;\n\n  if (appId === 'blazer') renderBlazer();\n  else if (appId === 'lime') renderLime();\n  else if (appId === 'moments') renderMoments();\n  else if (appId === 'bbs') renderBbs();\n  else if (appId === 'schedule') renderSchedule();\n  else if (appId === 'gallery') renderGallery();\n  else if (appId === 'worldbook') renderWorldbook();\n  else if (appId === 'settings') renderSettings();\n\n  var curEl = document.getElementById(currentStack[currentStack.length - 1]);\n  var targetEl = document.getElementById(target);\n  if (curEl && targetEl && curEl !== targetEl) {\n    curEl.classList.remove('on');\n    curEl.classList.add('under');\n    targetEl.classList.remove('under');\n    targetEl.classList.add('on');\n    currentStack.push(target);\n  }\n}\n\nfunction goBack() {\n  if (currentStack.length <= 1) return;\n  var curId = currentStack.pop();\n  var curEl = document.getElementById(curId);\n  var prevId = currentStack[currentStack.length - 1];\n  var prevEl = document.getElementById(prevId);\n  if (curEl) {\n    curEl.classList.remove('on');\n    curEl.classList.remove('under');\n  }\n  if (prevEl) {\n    prevEl.classList.remove('under');\n    prevEl.classList.add('on');\n  }\n}\n\nfunction goHome() {\n  while (currentStack.length > 1) {\n    var curId = currentStack.pop();\n    var el = document.getElementById(curId);\n    if (el) { el.classList.remove('on'); el.classList.remove('under'); }\n  }\n  var home = document.getElementById('scr-home');\n  if (home) { home.classList.remove('under'); home.classList.add('on'); }\n  activeChat = null;\n}\n\n// ===== 数据解析引擎 (落第骑士 MVU 数据规范) =====\nfunction resolvePlayer() {\n  var p = stat && stat.玩家 || {};\n  var ability = p.伐刀能力 || {};\n  var techniques = ability.招式 || {};\n  return {\n    name: p.姓名 || '未建档',\n    affiliation: p.所属 || '所属未登记',\n    rank: p.登记等级 || '—',\n    device: p.固有灵装 || '灵装未登记',\n    arts: Object.keys(techniques).join('、') || '尚无命名招式',\n    bio: p.角色简介 || '完成开局建档后，这里显示本局角色档案。',\n    mechanism: ability.能力本质 || '能力本质未登记',\n    category: ability.能力系别 || '系别未登记',\n    cost: ability.共通限制 || '共通限制未登记',\n    style: p.战斗风格 || '战斗风格未登记',\n    techniques: techniques,\n    otherAbilities: p.其他能力 || {},\n    sixAxes: p.六维 || {}\n  };\n}\n\nfunction resolveScene() {\n  var s = stat && stat.场景 || {};\n  return {\n    time: s.时间 || '时间未确认',\n    location: s.地点 || '地点未确认',\n    volume: s.当前卷 === 1 ? '第一卷' : '卷数未确认',\n    chapter: s.当前章 || '待选择',\n    phase: s.阶段 || '未读取'\n  };\n}\n\n// 刷新首页学生证\nfunction updateHomeScreen() {\n  var pl = resolvePlayer();\n  var sc = resolveScene();\n\n  var nameEl = document.getElementById('home-name');\n  if (nameEl) nameEl.textContent = pl.name;\n\n  var avaEl = document.getElementById('home-ava');\n  if (avaEl) avaEl.textContent = pl.name.slice(0, 1);\n\n  var classEl = document.getElementById('home-class');\n  if (classEl) classEl.textContent = pl.affiliation;\n\n  var rankEl = document.getElementById('home-rank');\n  if (rankEl) rankEl.textContent = pl.rank + '级';\n\n  var devEl = document.getElementById('home-device');\n  if (devEl) devEl.textContent = pl.device;\n\n  var artEl = document.getElementById('home-art');\n  if (artEl) artEl.textContent = pl.arts;\n\n  var clkEl = document.getElementById('sys-clk');\n  if (clkEl) clkEl.textContent = sc.time;\n\n  // 六维标签药丸\n  var axes = pl.sixAxes;\n  var map = [\n    { id: 'pill-atk', label: '攻', val: axes['攻击力'] || '—' },\n    { id: 'pill-def', label: '防', val: axes['防御力'] || '—' },\n    { id: 'pill-mp',  label: '魔', val: axes['魔力量'] || '—' },\n    { id: 'pill-ctrl',label: '控', val: axes['魔力控制'] || '—' },\n    { id: 'pill-phy', label: '体', val: axes['体能'] || '—' },\n    { id: 'pill-lck', label: '运', val: axes['运气'] || '—' }\n  ];\n  map.forEach(function(item) {\n    var el = document.getElementById(item.id);\n    if (el) {\n      el.className = 'axis-pill rank-' + item.val;\n      el.innerHTML = item.label + '<b>' + esc(item.val) + '</b>';\n    }\n  });\n}\n\n// ===== 伐刀者档案 (Blazer ID) =====\nfunction switchBlazerTab(tab) {\n  blazerSubTab = tab;\n  document.querySelectorAll('.subtab').forEach(function(el) {\n    el.classList.toggle('on', el.getAttribute('data-btab') === tab);\n  });\n  renderBlazer();\n}\n\nfunction rankToValue(r) {\n  var m = { 'A': 5.5, 'B': 4.3, 'C': 3.2, 'D': 2.2, 'E': 1.4, 'F': 0.8 };\n  return m[String(r).toUpperCase()] || 0;\n}\n\nfunction renderBlazer() {\n  var body = document.getElementById('blazer-body');\n  if (!body) return;\n  var pl = resolvePlayer();\n  var sc = resolveScene();\n\n  var headRank = document.getElementById('blazer-head-rank');\n  if (headRank) headRank.textContent = pl.rank + '级 伐刀者 // ' + pl.affiliation;\n\n  if (blazerSubTab === 'overview') {\n    body.innerHTML = \n      '<div class=\"card1\">' +\n        '<div class=\"ct\">破军学园 · 注册学员信息</div>' +\n        '<div style=\"display:flex;align-items:center;gap:12px;margin-bottom:10px;\">' +\n          '<div class=\"card-avatar\" style=\"width:54px;height:54px;font-size:22px;\">' + esc(pl.name.slice(0, 1)) + '</div>' +\n          '<div>' +\n            '<div style=\"font-size:17px;font-weight:800;color:var(--ink);\">' + esc(pl.name) + ' <span class=\"card-rank-badge\">' + esc(pl.rank) + '级</span></div>' +\n            '<div style=\"font-size:12px;color:var(--muted);margin-top:2px;\">所属：' + esc(pl.affiliation) + '</div>' +\n            '<div style=\"font-size:12px;color:var(--sky);margin-top:2px;\">灵装：' + esc(pl.device) + '</div>' +\n          '</div>' +\n        '</div>' +\n        '<div style=\"font-size:12.5px;color:var(--ink2);line-height:1.6;background:var(--card2);padding:10px 12px;border-radius:10px;\">' +\n          esc(pl.bio) +\n        '</div>' +\n      '</div>' +\n\n      '<div class=\"card1\">' +\n        '<div class=\"ct\">当前场景</div>' +\n        '<div style=\"font-size:12.5px;color:var(--ink2);line-height:1.6;\">' +\n          '<div><i class=\"ti ti-map-pin\" style=\"color:#ef4444;margin-right:4px;\"></i> 地点：<b>' + esc(sc.location) + '</b></div>' +\n          '<div style=\"margin-top:4px;\"><i class=\"ti ti-clock\" style=\"color:#38bdf8;margin-right:4px;\"></i> 时间：' + esc(sc.time) + '</div>' +\n          '<div style=\"margin-top:4px;\"><i class=\"ti ti-trophy\" style=\"color:#f59e0b;margin-right:4px;\"></i> 进度：' + esc(sc.volume + ' · ' + sc.chapter + ' · ' + sc.phase) + '</div>' +\n        '</div>' +\n      '</div>';\n  } else if (blazerSubTab === 'radar') {\n    var axesOrder = ['攻击力', '防御力', '魔力量', '魔力控制', '体能', '运气'];\n    var cx = 130, cy = 115, maxRadius = 75;\n    var points = [];\n    var webCircles = [0.25, 0.5, 0.75, 1.0];\n\n    var webSvg = '';\n    webCircles.forEach(function(lvl) {\n      var r = maxRadius * lvl;\n      var pts = [];\n      for (var i = 0; i < 6; i++) {\n        var angle = (Math.PI / 3) * i - Math.PI / 2;\n        pts.push((cx + r * Math.cos(angle)).toFixed(1) + ',' + (cy + r * Math.sin(angle)).toFixed(1));\n      }\n      webSvg += '<polygon class=\"radar-web\" points=\"' + pts.join(' ') + '\"/>';\n    });\n\n    var labelsSvg = '';\n    var pointNodes = '';\n    for (var i = 0; i < 6; i++) {\n      var angle = (Math.PI / 3) * i - Math.PI / 2;\n      var spokeX = (cx + maxRadius * Math.cos(angle)).toFixed(1);\n      var spokeY = (cy + maxRadius * Math.sin(angle)).toFixed(1);\n      webSvg += '<line class=\"radar-web-spoke\" x1=\"' + cx + '\" y1=\"' + cy + '\" x2=\"' + spokeX + '\" y2=\"' + spokeY + '\"/>';\n\n      var axisName = axesOrder[i];\n      var rk = pl.sixAxes[axisName] || '—';\n      var val = rankToValue(rk);\n      var ptR = (val / 6.0) * maxRadius;\n      var ptX = cx + ptR * Math.cos(angle);\n      var ptY = cy + ptR * Math.sin(angle);\n      points.push(ptX.toFixed(1) + ',' + ptY.toFixed(1));\n      pointNodes += '<circle class=\"radar-point\" cx=\"' + ptX.toFixed(1) + '\" cy=\"' + ptY.toFixed(1) + '\" r=\"3.5\"/>';\n\n      var labelR = maxRadius + 22;\n      var lx = cx + labelR * Math.cos(angle);\n      var ly = cy + labelR * Math.sin(angle);\n      labelsSvg += '<text class=\"radar-label\" x=\"' + lx.toFixed(1) + '\" y=\"' + (ly - 6).toFixed(1) + '\">' + axisName + '</text>';\n      labelsSvg += '<text class=\"radar-rank-badge\" x=\"' + lx.toFixed(1) + '\" y=\"' + (ly + 7).toFixed(1) + '\">' + esc(rk) + '</text>';\n    }\n\n    var polygonSvg = '<polygon class=\"radar-polygon\" points=\"' + points.join(' ') + '\"/>';\n\n    body.innerHTML = \n      '<div class=\"card1\">' +\n        '<div class=\"ct\">伐刀者 A~F 六维能力雷达评定</div>' +\n        '<div class=\"radar-container\">' +\n          '<svg class=\"radar-svg\" viewBox=\"0 0 260 230\">' +\n            webSvg +\n            polygonSvg +\n            pointNodes +\n            labelsSvg +\n          '</svg>' +\n        '</div>' +\n        '<div style=\"font-size:12px;color:var(--muted);text-align:center;margin-top:4px;\">' +\n          '日本伐刀者管理局破军支部 · 六维测定数据' +\n        '</div>' +\n      '</div>';\n  } else if (blazerSubTab === 'device') {\n    function listSkills(records) {\n      var names = Object.keys(records);\n      if (!names.length) return '<div class=\"noble-art-desc\">尚未登记具体能力。</div>';\n      return names.map(function(name) {\n        var skill = records[name] || {};\n        return '<div class=\"noble-art-block\"><div class=\"noble-art-title\">' + esc(name) + ' · ' + esc(skill.掌握状态 || '待确认') + '</div>' +\n          '<div class=\"noble-art-desc\">' + esc(skill.说明 || '说明未登记') + '</div>' +\n          '<div class=\"noble-art-desc\">条件与代价：' + esc(skill.条件与代价 || '未登记') + '</div></div>';\n      }).join('');\n    }\n    body.innerHTML = '<div class=\"card1\"><div class=\"ct\">固有灵装</div><div class=\"noble-art-title\">' + esc(pl.device) + '</div>' +\n      '<div class=\"ct\" style=\"margin-top:14px;\">伐刀能力 · ' + esc(pl.category) + '</div><p>' + esc(pl.mechanism) + '</p>' +\n      '<p>共通限制：' + esc(pl.cost) + '</p>' + listSkills(pl.techniques) +\n      '<div class=\"ct\" style=\"margin-top:14px;\">其他能力</div>' + listSkills(pl.otherAbilities) + '</div>';\n  } else if (blazerSubTab === 'roster') {\n    var relations = stat && stat.人际 || {};\n    var names = Object.keys(relations);\n    body.innerHTML = names.length ? '<div class=\"roster-list\">' + names.map(function(name) {\n      var relation = relations[name] || {};\n      return '<div class=\"roster-card\"><div class=\"roster-ava\">' + esc(name.slice(0, 1)) + '</div><div class=\"roster-info\">' +\n        '<div class=\"roster-name\">' + esc(name) + '</div><div class=\"roster-device\">' + esc(relation.关系 || '关系未确认') + '</div>' +\n        '<div class=\"roster-device\">' + esc(relation.态度印象 || '尚无印象记录') + '</div></div></div>';\n    }).join('') + '</div>' : '<div class=\"card1\">本局尚无已记录的人际关系。</div>';\n  }\n}\n\n// ===== 破军 LIME 通讯 =====\nfunction renderLime() {\n  var body = document.getElementById('lime-body');\n  if (!body) return;\n  document.getElementById('lime-title').textContent = activeChat || '破军 LIME';\n  document.getElementById('lime-sub').textContent = '通讯记录尚未接入';\n  body.innerHTML = '<div class=\"card1\"><div class=\"ct\">通讯</div>本局尚未接入私人通讯记录。请在酒馆聊天中进行角色交流。</div>';\n}\nfunction openLimeChat(name) { activeChat = name; renderLime(); }\nfunction renderLimeChatView(name) { activeChat = name; renderLime(); }\nfunction handleChatKey(e) { if (e.key === 'Enter') sendChatMsg(); }\nfunction sendChatMsg() { toast('通讯尚未接入，请在酒馆聊天中发送。'); }\nfunction sendQuickAction() { sendChatMsg(); }\n\n// ===== 学园圈 (Moments) =====\nfunction renderMoments() {\n  var body = document.getElementById('moments-body');\n  if (body) body.innerHTML = '<div class=\"card1\"><div class=\"ct\">学园圈</div>本局尚未接入动态记录。</div>';\n}\nfunction postMomentPrompt() { toast('动态发布尚未接入。'); }\n\n// ===== 破军 BBS 论坛 =====\nfunction renderBbs() {\n  var body = document.getElementById('bbs-body');\n  if (body) body.innerHTML = '<div class=\"card1\"><div class=\"ct\">破军 BBS</div>本局尚未接入论坛记录。</div>';\n}\nfunction refreshBbs() { renderBbs(); toast('当前没有可读取的论坛记录。'); }\n\n// ===== 第一卷剧情记录 =====\nfunction renderSchedule() {\n  var body = document.getElementById('schedule-body');\n  if (!body) return;\n  var scene = resolveScene();\n  var events = stat && stat.场景 && stat.场景.已发生事件 || {};\n  var names = Object.keys(events);\n  body.innerHTML = '<div class=\"card1\"><div class=\"ct\">当前剧情</div><div>' + esc(scene.volume + ' · ' + scene.chapter + ' · ' + scene.phase) + '</div>' +\n    '<p>' + esc(scene.time + ' · ' + scene.location) + '</p><button type=\"button\" onclick=\"openStoryControls()\">展开剧情控制</button></div>' +\n    '<div class=\"card1\"><div class=\"ct\">已发生事件</div>' + (names.length ? names.map(function(name) {\n      var event = events[name] || {};\n      return '<div class=\"noble-art-block\"><div class=\"noble-art-title\">' + esc(name) + ' · ' + esc(event.章段 || '') + '</div>' +\n        '<div class=\"noble-art-desc\">' + esc(event.结果 || '') + '</div></div>';\n    }).join('') : '尚无已记录事件。') + '</div>';\n}\nfunction openStoryControls() {\n  if (bridge && bridge.ui && typeof bridge.ui.openStoryControls === 'function') bridge.ui.openStoryControls();\n}\n\n// ===== 灵装画廊 (Gallery) =====\nfunction renderGallery() {\n  var body = document.getElementById('gallery-body');\n  if (!body) return;\n\n  body.innerHTML = \n    '<div class=\"card1\">' +\n      '<div class=\"ct\">灵装图鉴 · 图片尚未接入</div>' +\n      '<div style=\"display:grid;grid-template-columns:repeat(2, 1fr);gap:10px;margin-top:8px;\">' +\n        '<div style=\"background:var(--card2);height:120px;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted);font-size:12px;\">' +\n          '<i class=\"ti ti-photo\" style=\"font-size:28px;color:#ef4444;margin-bottom:4px;\"></i>' +\n          '<span>灵装显现 · 阴铁</span>' +\n        '</div>' +\n        '<div style=\"background:var(--card2);height:120px;border-radius:10px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted);font-size:12px;\">' +\n          '<i class=\"ti ti-flame\" style=\"font-size:28px;color:#f59e0b;margin-bottom:4px;\"></i>' +\n          '<span>一刀修罗 · 爆发</span>' +\n        '</div>' +\n      '</div>' +\n    '</div>';\n}\n\n// ===== 世界之理 (Worldbook) =====\nfunction renderWorldbook() {\n  var body = document.getElementById('worldbook-body');\n  if (!body) return;\n\n  body.innerHTML = \n    '<div class=\"card1\">' +\n      '<div class=\"ct\">设定资料目录 · 请以本卡世界书为准</div>' +\n      '<div style=\"font-size:12.5px;color:var(--ink2);line-height:1.6;\">' +\n        '<div style=\"display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--hair);\">' +\n          '<span>落第骑士英雄谭 · 世界观设定</span>' +\n          '<span style=\"color:#10b981;font-weight:700;\">资料条目</span>' +\n        '</div>' +\n        '<div style=\"display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--hair);\">' +\n          '<span>破军学园 · 选拔赛校规规则</span>' +\n          '<span style=\"color:#10b981;font-weight:700;\">资料条目</span>' +\n        '</div>' +\n        '<div style=\"display:flex;align-items:center;justify-content:space-between;padding:8px 0;\">' +\n          '<span>伐刀者能力体系与魔力量度</span>' +\n          '<span style=\"color:#10b981;font-weight:700;\">资料条目</span>' +\n        '</div>' +\n      '</div>' +\n    '</div>';\n}\n\n// ===== 终端配置 (Settings) =====\nfunction renderSettings() {\n  var body = document.getElementById('settings-body');\n  if (!body) return;\n\n  body.innerHTML = \n    '<div class=\"card1\">' +\n      '<div class=\"ct\">视觉与个性化</div>' +\n      '<div style=\"display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--hair);\">' +\n        '<span>色彩主题风格</span>' +\n        '<button onclick=\"toggleTheme()\" style=\"padding:4px 10px;background:var(--card2);border-radius:6px;font-size:12px;color:var(--ink);\">' +\n          '切换 黑底 / 白底' +\n        '</button>' +\n      '</div>' +\n      '<div style=\"display:flex;align-items:center;justify-content:space-between;padding:8px 0;\">' +\n        '<span>窗口与悬浮球位置</span>' +\n        '<button onclick=\"recenterWindow()\" style=\"padding:4px 10px;background:rgba(239,68,68,0.2);color:#fca5a5;border:1px solid rgba(239,68,68,0.4);border-radius:6px;font-size:12px;\">' +\n          '重置居中' +\n        '</button>' +\n      '</div>' +\n    '</div>' +\n    '<div class=\"card1\">' +\n      '<div class=\"ct\">系统版本信息</div>' +\n      '<div style=\"font-size:12px;color:var(--muted);line-height:1.6;\">' +\n        '<div>破军学园伐刀者便携智能终端 OS</div>' +\n        '<div>版本：v1.3.0 MONO ADV · 黑白轮盘版</div>' +\n        '<div>内核驱动：TavernHelper / MVU Data Bridge</div>' +\n      '</div>' +\n    '</div>';\n}\n\nfunction toggleTheme() {\n  var cur = document.documentElement.getAttribute('data-rk-theme');\n  var next = cur === 'light' ? 'dark' : 'light';\n  document.documentElement.setAttribute('data-rk-theme', next);\n  toast('已切换至 ' + (next === 'light' ? '黑白纸面' : '黑白墨色') + ' 主题');\n}\n\nfunction recenterWindow() {\n  if (bridge && bridge.ui && typeof bridge.ui.recenter === 'function') {\n    bridge.ui.recenter();\n  }\n  toast('终端位置已恢复屏幕中央');\n}\n\n// 引导启动函数：仅缓存本次显示数据，切换聊天或读取失败时清空。\nvar bridgeRevision = 0;\nfunction refreshTerminalView() {\n  updateHomeScreen();\n  var renderers = { 'scr-blazer': renderBlazer, 'scr-lime': renderLime, 'scr-moments': renderMoments, 'scr-bbs': renderBbs, 'scr-schedule': renderSchedule };\n  var render = renderers[currentStack[currentStack.length - 1]];\n  if (render) render();\n}\nfunction refreshTerminalState() {\n  var revision = ++bridgeRevision;\n  stat = {};\n  refreshTerminalView();\n  if (!bridge || typeof bridge.getStat !== 'function') return Promise.resolve();\n  return Promise.resolve().then(function() { return bridge.getStat(); }).then(function(value) {\n    if (revision !== bridgeRevision) return;\n    stat = value || {};\n    refreshTerminalView();\n  }).catch(function() {\n    if (revision !== bridgeRevision) return;\n    stat = {};\n    refreshTerminalView();\n  });\n}\nwindow.RKBoot = function(b) {\n  bridge = b;\n  refreshTerminalState();\n  if (bridge && typeof bridge.onUpdate === 'function') bridge.onUpdate(refreshTerminalState);\n};\n\n// 默认首屏就绪\nupdateHomeScreen();\n\n</script>\n<script>\n\n/* MONO ADV controls: menu keyboard operation and UI-only status badge. */\n(function () {\n  var root = document.querySelector('.home-content');\n  document.querySelectorAll('[data-layout-choice]').forEach(function (button) {\n    button.addEventListener('click', function () {\n      var layout = button.getAttribute('data-layout-choice');\n      root.setAttribute('data-layout', layout);\n      document.querySelectorAll('[data-layout-choice]').forEach(function (b) {\n        b.setAttribute('aria-pressed', b === button ? 'true' : 'false');\n      });\n    });\n  });\n  var items = Array.from(document.querySelectorAll('.mono-sector'));\n  items.forEach(function (item, index) {\n    function setLabel() {\n      document.getElementById('mono-wheel-label').textContent = item.getAttribute('data-label');\n      items.forEach(function (it) { it.setAttribute('tabindex', it === item ? '0' : '-1'); });\n    }\n    item.addEventListener('pointerenter', setLabel);\n    item.addEventListener('focus', setLabel);\n    item.addEventListener('keydown', function (e) {\n      var next = index;\n      if (e.key === 'Enter' || e.key === ' ') {\n        e.preventDefault(); openApp(item.getAttribute('data-app')); return;\n      }\n      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = (index + 1) % items.length;\n      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = (index + items.length - 1) % items.length;\n      else if (e.key === 'Home') next = 0;\n      else if (e.key === 'End') next = items.length - 1;\n      else return;\n      e.preventDefault(); items[next].focus();\n    });\n  });\n  document.addEventListener('keydown', function (e) {\n    if (e.key === 'Escape') {\n      if (currentStack.length > 1) goBack();\n      else if (bridge && bridge.ui) bridge.ui.close();\n    }\n  });\n  var originalUpdate = updateHomeScreen;\n  updateHomeScreen = function () {\n    originalUpdate();\n    var badge = document.getElementById('mono-source');\n    if (badge) {\n      var hasRecord = stat && (stat.玩家 || stat.player || stat.user);\n      badge.textContent = hasRecord ? 'MVU / 读取' : '原稿示例';\n      badge.title = hasRecord ? '已读取原有玩家字段；缺失字段仍沿用原稿回退值。' : '未读到原脚本支持的玩家字段；当前显示原稿内置示例。';\n    }\n  };\n  updateHomeScreen();\n})();\n\n</script>\n</body>\n</html>\n"; }

  async function mountVia(html, mode) {
    const f = HD.createElement('iframe');
    f.setAttribute('title', '破军战术终端');
    SS.host.appendChild(f);
    SS.iframe = f;
    try {
      await new Promise((res, rej) => {
        const to = setTimeout(() => rej(new Error(mode + ' 超时')), mode === 'blob' ? 3000 : 5000);
        f.onload = () => { clearTimeout(to); res(); };
        if (mode === 'blob') {
          SS.blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
          f.src = SS.blobUrl;
        } else {
          f.srcdoc = html;
        }
      });
      const boot = f.contentWindow && f.contentWindow.RKBoot;
      if (typeof boot !== 'function') throw new Error('RKBoot 缺失（' + mode + '）');
      boot(makeBridge());
    } catch(e) {
      try { f.remove(); } catch(_) {}
      if (SS.iframe === f) SS.iframe = null;
      if (mode === 'blob' && SS.blobUrl) { try { HW.URL.revokeObjectURL(SS.blobUrl); } catch(_) {} SS.blobUrl = null; }
      throw e;
    }
  }

  async function mountPhone() {
    if (SS.booted || SS.destroyed) return;
    if (SS.mounting) return SS.mounting;
    SS.mounting = (async () => {
      const html = embeddedPhoneHtml();
      try {
        try { await mountVia(html, 'srcdoc'); }
        catch (e1) { if (SS.destroyed) return; await mountVia(html, 'blob'); }
        if (!SS.destroyed) SS.booted = true;
      } catch (e) {
        console.error('[Hagun-Mono-Terminal] Mount failed:', e);
        showOrbTip('终端未能加载', '收起后再次打开可重试；请查看浏览器控制台。');
      } finally { SS.mounting = null; }
    })();
    return SS.mounting;
  }

  /* 桥接对象 (Bridge) */
  async function readStat() {
    const service = window.RakudaiStateController;
    if (!service || typeof service.capture !== 'function') throw new Error('剧情状态服务尚未就绪');
    const captured = await service.capture();
    return captured.state;
  }

  const updateCbs = [];
  function emit(ev) {
    updateCbs.forEach(cb => { try { cb(ev); } catch(_) {} });
  }

  function makeBridge() {
    return {
      getStat: async () => readStat(),
      onUpdate: (cb) => updateCbs.push(cb),
      setOrbBadge: (n) => {
        const b = SS.orb && SS.orb.querySelector('.b');
        if (!b) return;
        SS.badge = n | 0;
        b.textContent = SS.badge > 99 ? '99+' : String(SS.badge);
        b.style.display = SS.badge > 0 ? 'block' : 'none';
      },
      notify: (p) => {
        p = p || {};
        if (!p.title && !p.body) { clearOrbTip(); return; }
        if (SS.visible) return;
        showOrbTip(p.title, p.body);
      },
      ui: {
        close: hide,
        recenter: () => recenter(),
        openStoryControls: () => { if (statePanel) { statePanel.open = true; refreshStatePanel(); } }
      }
    };
  }

  /* 宿主事件监听 */
  function wireEvents() {
    const eon = fn('eventOn');
    if (!eon) return;
    const TE = window.tavern_events || {};
    function safeOn(ev, cb) {
      try { const r = eon(ev, cb); r && r.stop && SS.disposers.push(() => r.stop()); } catch(_) {}
    }

    safeOn(TE.VARIABLE_UPDATE_ENDED || 'mag_variable_update_ended', () => emit({ type: 'vars' }));
    safeOn('mag_variable_update_ended_for_zod', () => emit({ type: 'vars' }));
    safeOn(TE.GENERATION_ENDED || 'generation_ended', () => emit({ type: 'story-turn' }));
    safeOn(TE.CHAT_CHANGED || 'chat_changed', () => emit({ type: 'chat' }));
  }

  function onResize() {
    if (SS.visible) setMode(preferDrawer() ? 'drawer' : 'floating');
    placeOrb(clampOrb(SS.orbPos.x, SS.orbPos.y));
    placeOrbTip();
    placeWheel();
  }

  function destroy() {
    if (SS.destroyed) return;
    SS.destroyed = true;
    disposeStatePanel();
    updateCbs.length = 0;
    try { SS.wheel && SS.wheel.remove(); SS.wheelBackdrop && SS.wheelBackdrop.remove(); } catch (_) {}
    try { if (HW.RKTacticalToggle === toggle) delete HW.RKTacticalToggle; } catch (_) {}
    while (SS.disposers.length) { try { SS.disposers.pop()(); } catch(_) {} }
    try { HW.removeEventListener('resize', onResize); } catch(_) {}
    try { SS.iframe && SS.iframe.remove(); } catch(_) {}
    try { SS.host && SS.host.remove(); } catch(_) {}
    try { SS.orb && SS.orb.remove(); } catch(_) {}
    try { SS.style && SS.style.remove(); } catch(_) {}
    try { SS.blobUrl && HW.URL.revokeObjectURL(SS.blobUrl); } catch(_) {}
    try { delete HW[SLOT]; } catch(_) {}
  }

    // This view and its token are disposable. MVU remains the only saved story state.
  let statePanel = null;
  let stateCapture = null;
  let panelBusy = false;
  let panelRequest = 0;
  const panelChapters = ['序章', '第一章', '第二章', '第三章', '第四章', '终章'];

  function stateService() {
    const service = window.RakudaiStateController;
    if (!service || typeof service.capture !== 'function' || typeof service.transition !== 'function') {
      throw new Error('剧情状态服务尚未就绪，请刷新后重试。');
    }
    return service;
  }

  function panelText(selector, value) {
    const node = statePanel && statePanel.querySelector(selector);
    if (node) node.textContent = value;
  }

  function updatePanelActions() {
    if (!statePanel) return;
    const state = stateCapture && stateCapture.state;
    const system = state && state.系统 || {};
    const scene = state && state.场景 || {};
    const select = statePanel.querySelector('select');
    const chapter = scene.当前章 === '待选择' ? select.value : scene.当前章;
    const ready = !panelBusy && !!stateCapture && system.开局状态 === '已建档' && system.主角模式 !== '未选择' && scene.当前卷 === 1;
    const located = typeof scene.时间 === 'string' && scene.时间.trim() && typeof scene.地点 === 'string' && scene.地点.trim();
    select.disabled = panelBusy || !stateCapture || scene.当前章 !== '待选择';
    statePanel.querySelector('[data-story-action="refresh"]').disabled = panelBusy;
    statePanel.querySelector('[data-story-action="start"]').disabled = !ready || scene.阶段 !== '未开始' || !located || !panelChapters.includes(chapter);
    statePanel.querySelector('[data-story-action="end"]').disabled = !ready || scene.阶段 !== '进行中';
    statePanel.querySelector('[data-story-action="next"]').disabled = !ready || scene.阶段 !== '已结束' || scene.当前章 === '终章';
    statePanel.setAttribute('aria-busy', String(panelBusy));
  }

  function renderStatePanel() {
    const state = stateCapture && stateCapture.state;
    const system = state && state.系统 || {};
    const scene = state && state.场景 || {};
    panelText('[data-story-summary]', '第一卷剧情 · ' + (scene.当前章 || '未读取') + ' / ' + (scene.阶段 || '未读取'));
    panelText('[data-story-system]', '系统：' + (system.开局状态 || '未读取') + ' · ' + (system.主角模式 || '未选择'));
    panelText('[data-story-scene]', '场景：' + (scene.当前卷 === 1 ? '第一卷' : '卷数未确认') + ' · ' + (scene.当前章 || '未读取') + ' · ' + (scene.阶段 || '未读取'));
    panelText('[data-story-location]', '时间：' + (scene.时间 || '未确认') + '　地点：' + (scene.地点 || '未确认'));
    if (panelChapters.includes(scene.当前章)) statePanel.querySelector('select').value = scene.当前章;
    let hint = '按钮只确认剧情阶段；事件结果仍依据实际对话记录。';
    if (system.开局状态 !== '已建档') hint = '请先完成建档，再确认时间、地点并开始剧情。';
    else if (!scene.时间 || !scene.地点) hint = '请先在聊天中确认本章时间和地点，再开始剧情。';
    else if (scene.当前章 === '待选择') hint = '选择从第一卷的哪一章开始，然后点击“开始本章”。';
    else if (scene.当前章 === '终章' && scene.阶段 === '已结束') hint = '第一卷已结束；此面板不切换到其他卷。';
    panelText('[data-story-hint]', hint);
    updatePanelActions();
  }

  async function refreshStatePanel() {
    if (!statePanel || SS.destroyed || panelBusy) return;
    const request = ++panelRequest;
    panelBusy = true;
    updatePanelActions();
    panelText('[data-story-status]', '正在读取当前聊天状态…');
    try {
      const captured = await stateService().capture();
      if (request !== panelRequest || SS.destroyed || !statePanel) return;
      if (!captured || !captured.state || !captured.token) throw new Error('未取得可用的剧情状态，请完成建档后刷新。');
      stateCapture = captured;
      renderStatePanel();
      panelText('[data-story-status]', '已读取当前聊天状态。');
    } catch (error) {
      if (request !== panelRequest || SS.destroyed || !statePanel) return;
      stateCapture = null;
      renderStatePanel();
      panelText('[data-story-status]', error && error.message || String(error));
    } finally {
      if (request === panelRequest && !SS.destroyed && statePanel) {
        panelBusy = false;
        updatePanelActions();
      }
    }
  }

  async function performStoryAction(action) {
    if (!statePanel || !stateCapture || panelBusy || SS.destroyed) return;
    const button = statePanel.querySelector('[data-story-action="' + action + '"]');
    if (!button || button.disabled) return;
    const captured = stateCapture;
    const options = { action };
    if (action === 'start' && captured.state.场景.当前章 === '待选择') options.chapter = statePanel.querySelector('select').value;
    panelBusy = true;
    updatePanelActions();
    panelText('[data-story-status]', '正在保存剧情阶段…');
    let failure = '';
    try {
      await stateService().transition(captured.token, options);
      emit({ type: 'vars' });
    } catch (error) {
      failure = error && error.message || String(error);
    } finally {
      if (!SS.destroyed && statePanel) {
        panelBusy = false;
        await refreshStatePanel();
        if (failure) panelText('[data-story-status]', failure + '（已重新读取当前状态）');
      }
    }
  }

  function buildStatePanel() {
    statePanel = HD.createElement('details');
    statePanel.id = 'rk-story-panel';
    statePanel.open = true;
    statePanel.innerHTML = '<summary><span data-story-summary>第一卷剧情 · 未读取</span></summary>' +
      '<div class="rk-story-content"><p data-story-system></p><p data-story-scene></p><p data-story-location></p>' +
      '<label>起始章节 <select aria-label="选择第一卷起始章节"><option value="">请选择章节</option>' +
      panelChapters.map(chapter => '<option value="' + chapter + '">' + chapter + '</option>').join('') + '</select></label>' +
      '<div class="rk-story-actions"><button type="button" data-story-action="refresh">刷新</button>' +
      '<button type="button" data-story-action="start">开始本章</button><button type="button" data-story-action="end">结束本章</button>' +
      '<button type="button" data-story-action="next">进入下一章</button></div>' +
      '<p data-story-hint></p><p data-story-status role="status" aria-live="polite"></p></div>';
    SS.host.querySelector('.bar').after(statePanel);
    statePanel.querySelector('select').addEventListener('change', updatePanelActions);
    statePanel.addEventListener('click', event => {
      const button = event.target.closest('[data-story-action]');
      if (!button || !statePanel.contains(button) || button.disabled) return;
      const action = button.getAttribute('data-story-action');
      if (action === 'refresh') refreshStatePanel();
      else performStoryAction(action);
    });
    statePanel.addEventListener('toggle', () => { if (statePanel && statePanel.open) refreshStatePanel(); });
    updateCbs.push(() => {
      if (SS.visible) refreshStatePanel();
      else { stateCapture = null; updatePanelActions(); }
    });
    refreshStatePanel();
  }

  function disposeStatePanel() {
    ++panelRequest;
    stateCapture = null;
    statePanel = null;
  }


  buildDom();
  buildStatePanel();
  bindDrag();
  wireEvents();

  SS.host.querySelector('[data-a="x"]').onclick = hide;
  SS.host.querySelector('[data-a="min"]').onclick = hide;
  HW.addEventListener('resize', onResize);
  window.addEventListener('pagehide', destroy);
  SS.disposers.push(() => window.removeEventListener('pagehide', destroy));
  if (HW.visualViewport) {
    HW.visualViewport.addEventListener('resize', onResize);
    HW.visualViewport.addEventListener('scroll', onResize);
    SS.disposers.push(() => {
      HW.visualViewport.removeEventListener('resize', onResize);
      HW.visualViewport.removeEventListener('scroll', onResize);
    });
  }

  HW[SLOT] = { destroy, show, hide, toggle, recenter, toggleWheel, openApp: openPhoneApp, version: '1.3.0' };
  try { HW.RKTacticalToggle = toggle; } catch(_) {}

  console.info('[Hagun-Blazer-Terminal] initialized');
})();
